import mlflow, warnings, json
warnings.filterwarnings("ignore")

client = mlflow.MlflowClient()

# Get medgemma_evaluate traces from default experiment
traces = client.search_traces(
    experiment_ids=["0"],
    max_results=300,
    order_by=["timestamp_ms DESC"],
)

# Find the 4 Ankylosing Spondylitis traces (most recent run)
as_traces = []
for t in traces:
    tags = t.info.tags or {}
    if tags.get("mlflow.traceName") != "medgemma_evaluate":
        continue
    spans = t.data.spans or []
    for s in spans:
        inp = s.inputs or {}
        prompt = inp.get("prompt", "")
        if "Ankylosing" in prompt:
            as_traces.append((t, s))
            break

print(f"Found {len(as_traces)} AS traces (showing most recent 4)\n")

# Show the 4 most recent (= our harness run)
for i, (t, s) in enumerate(as_traces[:4]):
    inp = s.inputs or {}
    out = s.outputs or {}
    prompt = inp.get("prompt", "")
    response = out.get("response", "")

    # Detect variant
    has_rules = "9. When the entity text" in prompt
    has_crosscheck = "Cross-check" in prompt
    if has_rules and has_crosscheck:
        variant = "combined"
    elif has_rules:
        variant = "specificity_guard"
    elif has_crosscheck:
        variant = "context_emphasis"
    else:
        variant = "baseline"

    # Extract just the system prompt section to see what was added
    sys_section = ""
    if "[system]" in prompt and "[user]" in prompt:
        sys_section = prompt.split("[user]")[0]

    print(f"{'='*80}")
    print(f"TRACE {i+1}: {variant} (ts={t.info.timestamp_ms})")
    print(f"{'='*80}")

    # Show what extra rules were in the system prompt (last 600 chars)
    if has_rules or has_crosscheck:
        print(f"--- System prompt tail (variant additions) ---")
        if has_rules:
            idx = sys_section.find("9. When the entity text")
            if idx >= 0:
                print(sys_section[idx:idx+300])
        if has_crosscheck:
            idx = prompt.find("Cross-check")
            if idx >= 0:
                print(prompt[idx:idx+300])
    else:
        print("--- No prompt modifications (baseline) ---")

    print(f"\n--- MedGemma Raw Response ---")
    print(response[:1500])
    print()
