import mlflow, warnings
warnings.filterwarnings("ignore")

client = mlflow.MlflowClient()
traces = client.search_traces(
    experiment_ids=["0"],
    max_results=300,
    order_by=["timestamp_ms DESC"],
)

# Get ALL AS medgemma_evaluate traces, show the model's actual reasoning
as_evals = []
for t in traces:
    tags = t.info.tags or {}
    if tags.get("mlflow.traceName") != "medgemma_evaluate":
        continue
    spans = t.data.spans or []
    for s in spans:
        inp = s.inputs or {}
        prompt = inp.get("prompt", "")
        if "Ankylosing" in prompt:
            as_evals.append((t, s))
            break

# Get the corresponding gemini_structure_decision traces (paired by proximity in time)
as_structs = []
for t in traces:
    tags = t.info.tags or {}
    if tags.get("mlflow.traceName") != "gemini_structure_decision":
        continue
    spans = t.data.spans or []
    for s in spans:
        out = s.outputs or {}
        resp = out.get("response", "")
        if "C0038013" in resp or "C0409675" in resp:
            as_structs.append((t, s))
            break

# Match them: the harness ran 4 variants, each does medgemma_evaluate then gemini_structure
# Most recent first. Our run had 6 entities x 4 variants = 24 medgemma calls
# AS is entity 3 in each variant pass

# Get the 4 most recent AS eval+struct pairs
recent_evals = as_evals[:4]  # combined, context_emphasis, specificity_guard, baseline (reverse order)
recent_structs = as_structs[:4]

for i, ((te, se), (ts_t, ss)) in enumerate(zip(recent_evals, recent_structs)):
    inp = se.inputs or {}
    out_eval = se.outputs or {}
    out_struct = ss.outputs or {}

    prompt = inp.get("prompt", "")
    medgemma_response = out_eval.get("response", "")
    gemini_output = out_struct.get("response", "")

    # Detect variant
    has_rules = "9. When the entity text" in prompt
    has_crosscheck = "Cross-check" in prompt
    if has_rules and has_crosscheck:
        variant = "combined"
    elif has_rules:
        variant = "specificity_guard"
    elif has_crosscheck:
        variant = "context_emphasis"
    else:
        variant = "baseline"

    # Extract MedGemma's actual analysis (after <start_of_turn>model or the prompt echo)
    model_output = medgemma_response
    if "<start_of_turn>model" in model_output:
        model_output = model_output.split("<start_of_turn>model")[-1]
    # Sometimes it starts with "Output:" prefix
    if "Output:" in model_output:
        model_output = model_output[model_output.index("Output:"):]

    print(f"{'='*80}")
    print(f"VARIANT: {variant}")
    print(f"{'='*80}")
    print(f"\n--- MedGemma Reasoning (after prompt echo) ---")
    print(model_output[:2000].strip())
    print(f"\n--- Gemini Final Decision ---")
    print(gemini_output[:400])
    print()
